"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9021],{9021:(t,e,i)=>{i.d(e,{Sv:()=>x,JA:()=>a,p_:()=>n,Qq:()=>r});let d=JSON.parse('{"$note":"כל מילה בפרק 4 חיה כאן, פעם אחת. הפריסה (layout.json) מפנה לקטעים לפי מזהה — היא לא כותבת טקסט. כך ההבטחה \'כל משפט מופיע פעם אחת\' נבדקת במכונה: concept/chapter4/verify-chapter4.mjs מוודא שכל קטע קיים ב-SOURCE-TEXT.md ושכל קטע נצרך בדיוק פעם אחת.","number":4,"title":"ההגירה והקרבות","menuTitle":"פרק 4 \xb7 ההגירה והקרבות","passages":{"\xa70":[{"id":"a","text":"גם לאחר אירוע זה תושבי מכה לא השתכנעו שמוחמד אכן נביא אמת, ולא שעו לקריאותיו לעזוב את עבודת האלילים.","page":"גם לאחר המסע הלילי והעלייה לשמיים שנלמדו בפרק שעבר, תושבי מכה לא השתכנעו שמוחמד אכן נביא אמת, ולא שעו לקריאותיו לעזוב את עבודת האלילים."},{"id":"b","text":"בשל כך, מוחמד נאלץ להגר עם חבריו המעטים שצבר לאורך 12 השנים במכה.","page":"הניסיונות הכושלים של מוחמד להפיץ את בשורת האסלאם במכה וסביבותיה קיבלו תפנית כאשר עולי רגלים מהעיר ית\'רב ניקרו בדרכו של מוחמד באתרי הפולחן סביב תקופת החג\'."}],"\xa71":[{"id":"a","text":"מוחמד בחר להגר ליישוב ית\'רב הנמצא למעלה מ-300 ק\\"מ צפונית לעיר מכה, שם התגוררו מספר שבטים - שבט אוס וחזרג\' הערבים,","page":"בעיר ית\'רב, שהייתה למעשה אסופת כפרים, ישבו שני שבטים ערביים - אַוּס\' וְחַ\'זְרַג\', ושלושה שבטים יהודים - נַדִיר, קֻרַיְטַ\'ה וקַיְנוּקַאע."},{"id":"b","text":"ועוד שלושה שבטים יהודים - בני נדיר, בני קריזה ובני קינקאע שלמעשה התיישבו שם עוד לפני שהגיעו השבטים הנוספים.","page":"המפגשים עם השבטים הולידו את רעיון ההגירה לית\'רב, ששמה הוחלף ל-אלמַדִינַה, כלומר העיר (בה\' הידיעה) - עירו של הנביא."}],"\xa72":[{"id":"flight","text":"המיסגור של ההגירה למדינה, כאילו הייתה בריחה של מוחמד בשל העובדה שהיה נרדף, מייצר בעיה באסלאם, שכן זו זילות לומר שהנביא נרדף על ידי בני עמו.","page":"המיסגור של מוחמד כפליט המבקש הגנה מאנשי ית\'רב הוא לא היחיד, שכן מסורות רבות נכרכו גם סביב הנרטיב שההגירה לא הייתה בגלל הצורך להימלט, אלא אנשי ית\'רב הזמינו אותו להיות בורר בסכסוכים בין השבטים, ואם כן ההגירה למדינה הייתה לטובתם של השבטים שחיו שם, שזכו במנהיג ומושיע שיגאל אותם מסכסוכי הדמים ארוכי השנים ביניהם."},{"id":"invited","text":"מסיבה זו, התקבע הנרטיב, לפיו השבטים אוס וחזרג\' הזמינו את מוחמד לשמש כבורר בסכסוכים ביניהם, בעיקר על אדמות.","omitted":true,"$omitted-note":"סבב התיקונים של המרצה (18.9.2026): הנרטיב של ההזמנה נאמר בתוך הפסקה שלה על המיסגור (page של \xa72.flight). הקטע קיים ונבדק, אינו מודפס."}],"\xa73":[{"id":"a","term":"אלאנצאר","text":"בהגיעו לית\'רב קיבלו אותו השבטים בסבר פנים יפות ונקראו \\"התומכים\\" (אלאנצאר)."},{"id":"b","text":"כך, בערים מכה וית\'רב התגוררו ארבע קבוצות אנשים:","page":"חצי האי ערב התחלקה לארבע גורמים ראשיים:"},{"id":"muhajirun","name":"המהגרים","text":"חברי הנביא שהגיעו ממכה;","page":"המהגרים (אלמהאג\'רון) - הקבוצה הנאמנה למוחמד שהיגרו איתו ממכה למדינה"},{"id":"ansar","name":"התומכים","text":"תושבי ית\'רב שסייעו לנביא בכך שקלטו אותו ואת המהגרים בעירם;","page":"התומכים (אלאנצאר) - התומכים משבטי אוס וח\'זרג\' שקיבלו את פניו בסבר פנים יפות והצטרפו לחוזה האומה"},{"id":"jews","text":"שלושת השבטים היהודים במדינה,","page":"היהודים - שלושת השבטים של היהודים שהתגוררו בית\'רב"},{"id":"quraysh","text":"ובמכה התגוררו הכופרים משבט קריש.","page":"הכופרים - שבט קורייש, שבטו של מוחמד, בעיר מכה"}],"\xa74":[{"id":"a","text":"בהגיעו למדינה (ית\'רב לשעבר) כתב מוחמד חוזה עם בני המקום הנקרא \\"חוזה האומה\\" והתחיל לבסס את קהילת המאמינים במקום."},{"id":"b","text":"כך, לראשונה לאחר 12 שנים של אי הצלחה, דשדוש וחוסר יכולת לבסס את דת האסלאם, נהיה מוחמד ראש ישות מדינית בעלת דת, מוסר, ערכים וצבא."}],"\xa75":[{"id":"a","term":"אלהג\'רה","text":"ההגירה (אלהג\'רה\') היא אירוע מרכזי ומכונן בדת האסלאם, ולא לחינם הלוח השנה המוסלמי מתחיל משנת ההגירה (622 לספירה, ראו להלן: עמר, הח\'ליף השני)."},{"id":"b","text":"להגירה יש סמליות דתית עמוקה של עקירה ממקום שבו המוסלמי אינו יכול לקיים את דתו לעבר מקום אחר שבו הדבר מתאפשר לו."}],"\xa76":[{"id":"echo1","text":"כך, למשל, קבוצת הג\'האדיסטים המצריים אשר רצחו את נשיא מצרים אנואר סאדאת (1981) כינתה את עצמה ג\'מאעת\' אלתכפיר ואלהג\'רה\' (קבוצת המכריזים כפירה והמהגרים) מפני שראו במוסלמים כגון סאדאת כופרים וכן עזבו ליישובים מרוחקים מהמשטר לשם מאבק)."},{"id":"echo2","text":"בהמשך, בתחילת המאה ה-21, קבוצות של הג\'האד הסלפי באירופה, היגרו לסוריה במטרה להילחם בכופרים הכובשים את אדמת האסלאם."}],"\xa77":[{"id":"a","text":"המסורת המוסלמית מספרת כי כאשר מוחמד הגיע למדינה, עצר הגמל עליו רכב בחצר השייכת לשני יתומים מקומיים.","page":"המסורת מספרת כי כאשר מוחמד הגיע למדינה, עצר הגמל עליו רכב בחצר השייכת לשני יתומים מקומיים."},{"id":"b","text":"כאשר הגמל כרע והתיישב, אמר מוחמד כי זהו סימן מאללה כי זה המקום שבו הוא יבנה את המסגד שלו, ורכש מהיתומים את הקרקע ההיא בעשרה דינרים."},{"id":"c","text":"מוחמד פינה את האלילים שהיו שם, וכן כרת את עצי הדקל ובנה את המסגד."}],"\xa78":[{"id":"a","term":"פתנה","text":"חוזה האומה שמוחמד עשה בהגיעו למדינה כלל אסלום של תושבי העיר ואיסור המלחמה ביניהם (פתנה), וכן יישוב הסכסוכים בין השבטים המקומיים.","page":"עם הגיעו למדינה, ביסס מוחמד את חוזה האומה המוסלמית (עַהְד אַלְאֻמַּה) שעיקרה הייתה המרה לדת האסלאם של השבטים הערביים, איסור מלחמה ביניהם (פִתְנָה), וכן יישוב הסכסוכים ארוכי השנים ביניהם."},{"id":"b","text":"ליהודים שחיו בית\'רב ניתנו זכויות כמו של השבטים המקומיים שהתאסלמו, אך מוחמד אסר עליהם במסגרת החוזה לכרות בריתות עם הכופרים במכה.","page":"ליהודים שחיו בית\'רב ניתנו זכויות כמו של השבטים שהתאסלמו, למרות שנשארו ביהדותם, אך במסגרת החוזה אסר עליהם מוחמד לכרות ברית עם הכופרים ממכה."},{"id":"c","text":"לימים, התפתחו סכסוכים בין צבא המאמינים של מוחמד במדינה לבין השבטים היהודיים, ובתגובה לכך את חלקם הוא גירש ואת השאר הרג."},{"id":"d","text":"המסורת המוסלמית מספרת על יהודים שהתאסלמו במטרה להינצל ממוות, והעשירו את האסלאם במסורות יהודיות."}],"\xa79":[{"id":"dawa","term":"דעוה","text":"לאחר שהיגר מוחמד למדינה וביסס את חוזה האומה, קיבל רשות מאללה לעבור ממצב של הטפה (דעוה)"},{"id":"jihad","term":"ג\'האד","text":"למצב של ג\'האד נגד הכופרים ממכה, וזאת בשל ההשתלטות שלהם על הנכסים והממון של המהגרים עם מוחמד."},{"id":"b","text":"וכך פתח צבאו של מוחמד בסדרה של קרבות, שמטרתם היו לבזוז את השלל של הכופרים ולהרוג אותם."},{"id":"c","text":"לקרבות אלו יש בין היתר קשר בל יינתק עם גירוש היהודים ממדינה במרוצת השנים הבאות."}],"\xa710":[{"id":"a","text":"הקרב התרחש ב-17 לחודש רמדאן בשנה השניה להג\'רה (624) בבאר בדר, הנמצא בקצהו המערבי של חצי האי ערב, בדרך בין מכה למדינה."},{"id":"b","text":"האזור שימש כמקום חניה מועדף על שיירות בשל היכולת של השיירות להשקות את הצאן והגמלים מבארות המים במקום."}],"\xa711":[{"id":"a","text":"השיירה שחזרה מסוריה למכה הצליחה להתקדם לעבר העיר, אך כוחות האבטחה שנשלחו ממכה ובראשם אבו ג\'הל ואבו סופיאן התקדמו לעבר צבאו של מוחמד במטרה להילחם בהם."},{"id":"muslims","text":"צבאו של מוחמד מנה מעט יותר מ-300 איש ומספר קטן של בהמות,"},{"id":"quraysh","text":"לעומת צבאו של אבו ג\'הל שמנה כ-1000 איש ועוד מספר רב של בהמות."}],"\xa712":[{"id":"rain","text":"המסורת אומרת כי בלילה שלפני הקרב ניתך גשם עז על צבאו של אבו ג\'הל שהיה בעמק בדר, ושיבש לו את היכולת לנווט לעבר צבאו של מוחמד."},{"id":"duel","text":"לאחר דו-קרב (מנהג נפוץ במלחמות באותם הימים) בין שלושה אנשי צבא בכירים מצבאו של מוחמד לבין שלושה בכירים מצבא הכופרים, פשטו אנשי מוחמד על הכופרים והצליחו להרוג שבעים מהם ולשבות מספר דומה של כופרים, לעומת צבא מוחמד שאיבד מספר קטן של לוחמים."}],"\xa713":[{"id":"a","text":"קרב בדר היה הקרב הראשון של צבא האסלאם, וחרף היותם מעטים מול רבים, באה להם ישועה וניצחון מזהיר."},{"id":"b","text":"הקוראן מתייחס באריכות לאירוע קרב בדר, ומכנה אותו בין היתר \\"יום הישועה\\", כלומר יום בו המוסלמי יודע להבחין בין האמת לשקר."}],"\xa714":[{"id":"a","text":"בשל חשיבותו הסמלית לאסלאם, מוזכר קרב בדר באופן מפורש בקוראן, תופעה חריגה למבנה הקוראן (ראו להלן: הקוראן) בו לרוב קיימים אזכורים רפרנסיים לאירועים, וכך נאמר (3:123):"},{"id":"verse","text":"אללה כבר חש לעזרתכם בבדר כאשר הייתם נחותים ..."}],"\xa715":[{"id":"a","text":"המסורת המוסלמית מספרת כי בעקבות קרב בדר ירדו למוחמד פסוקים רבים מפרשת השלל (8), ביניהם פסוק 17:","page":"המסורת מספרת כי בעקבות קרב בדר ירדו למוחמד פסוקים רבים מסורת השלל (8), ביניהם פסוק 17:"},{"id":"verse","text":"לא אתם הרגתם אותם כי אם אללה, ולא אתה ידית [את העפר], עת ידית, כי אם אללה"},{"id":"echo","text":"תנועות ההתנגדות חמאס וחזבאללה משתמשים במוטיב הפסוק הזה כאשר יורים טילים וכטב\\"מים על מדינת ישראל, וכן איראן נוהגת לכתוב על הטילים שלה שמשגרת לישראל, את הפסוק הזה, כמו גם הקראת הפסוק בשעת השיגור.","page":"תנועות ההתנגדות חמאס, חזבאללה וכן משמרות המהפכה באיראן, משתמשים במוטיב הפסוק הזה כאשר יורים טילים וכטב\\"מים על מדינת ישראל, וכן איראן נוהגת לכתוב על הטילים שלה שמשגרת לישראל, את הפסוק הזה, כמו גם הקראת הפסוק בשעת השיגור."}],"\xa716":[{"id":"a","text":"ישנה משמעות סמלית באסלאם לכך שהקרב היה בחודש רמדאן, והוא מהווה השראה לקרבות של האויבים שלנו."},{"id":"echo","text":"כך למשל, מלחמת יום הכיפורים (6 באוקטובר 1973) נפתחה בחודש רמדאן, במבצע צליחת התעלה של צבא מצרים, אותו כינו \\"מערכת בדר\\" על שם קרב בדר המיתולוגי של צבא מוחמד."}],"\xa717":[{"id":"a","text":"שבט קוריש בקשו לנקום במוסלמים על מפלתם בקרב בדר, וכשנה לאחר מכן יצאו (625) בני קוריש למלחמה בצבאו של מוחמד בהר אחד, צפונית למדינה."},{"id":"quraysh","text":"בקרב זה הכופרים משבט קוריש גייסו כ-3000 לוחמים ועוד מאות רבות של גמלים."},{"id":"muslims","text":"צבא מוחמד מנה כ-1000 לוחמים."}],"\xa718":[{"id":"a","text":"מסורות רבות קיימות על קרב זה, ביניהם זה שהלוחמים המוסלמים לא רצו לצאת למלחמה מפחד פן יפסידו במלחמה."},{"id":"b","text":"לאחר שמוחמד גער בהם, אללה הוריד פסוק האומר כי למרות העובדה שהמוסלמים נכנעו למורך לבבם, הרי שהדבר נסלח להם."}],"\xa719":[{"id":"a","text":"המסורת אומרת כי בקרב זה נטלו הנשים משבט קוריש חלק גדול בעיקר בעיצוב התודעה באמצעות דקלום שירים במטרה להעלות את המורל בקרב הלוחמים."},{"id":"b","text":"הקרב הסתיים ללא הכרעה ברורה, ובוודאי לא בניצחון צבא מוחמד."},{"id":"c","text":"מספר רב של לוחמים מוסלמים נפלו בקרב, ביניהם חמזה דודו של מוחמד."}],"\xa720":[{"id":"a","text":"חמזה היה גבר חזק, ונקרא","page":"חמזה היה גבר חזק ונקרא אבי השהידים, אריה של אללה ואריה של שליחו (אַסַד אַלְלָּה ואַסַד רַסוּלַה)"},{"id":"saying","text":"אדון השהידים; אריה אללה ואריה שליחו","omitted":true,"$omitted-note":"סבב התיקונים של המרצה (18.9.2026): המשפט על חמזה נאמר בנוסחה, בשדה page של \xa720.a, והוא כולל את הכינוי והתעתיק. הקטע קיים ונבדק, אינו מודפס."},{"id":"translit","text":"(סיד אלשהדאא\', אסד אללה ואסד רסולה).","omitted":true,"$omitted-note":"סבב התיקונים של המרצה (18.9.2026): המשפט על חמזה נאמר בנוסחה, בשדה page של \xa720.a, והוא כולל את הכינוי והתעתיק. הקטע קיים ונבדק, אינו מודפס."},{"id":"hind","text":"קיימת מסורת באסלאם על כך שאשתו של אבו סופיאן, הנד בנת עתבה, שכרה עבד שיביא לה את חמזה לאחר מותו, וכשהוא הובא לפניה, היא שתתה את הכבד שלו כנקמה על כך שהרג את קרוביה בקרב בדר."}],"\xa721":[{"id":"a","text":"המוסלמים פחדו כי המתים בקרב נהרגו לחינם, ואללה בישר להם כי יש להם שכר גדול בגן עדן."},{"id":"b","term":"שהידים","text":"הפסוק שלפי המסורת ירד לאחר קרב אחד נקרא פסוק \\"השהידים\\" האומר (סורת בית עמרם, פסוק 169):"},{"id":"verse","text":"אל תחשוב כי הנהרגים לשם אללה מתים המה. לא, כי חיים הם ואצל אללה פרנסתם"}],"\xa722":[{"id":"echo","term":"אבטאל","text":"פסוק זה נאמר בכל הלוויה ואזכרה של \\"שהידים\\" בקרב ארגוני הטרור, וכן נכתב על פוסטרים של מחבלים שנהרגו ומתקבלים כגיבורים (אבטאל) בקרב המחבלים.","page":"פסוק זה נאמר בכל הלווה ואזכרה של שהידים בקרב ארגוני הטרור, נכתב על פוסטים של שהידים ש\\"נהרגו בקרב\\", וכן עשוי להיות מצוטט בפיהם של מחבלים המתכוונים לצאת לעשות פיגוע."}],"\xa723":[{"id":"a","text":"בשנת 627 צרו על העיר מדינה שבט קוריש ושבטים נוספים מחצי האי ערב."},{"id":"cause1","text":"הרקע למצור נתון לפרשנות, ויש התולים את זה בחששם של תושבי מכה ממעשי ביזה ונקמה שהמוסלמים ממדינה תכננו לבצע בתושבי מכה בתגובה לקרב אחד,"},{"id":"cause2","text":"ויש התולים את זה ביהודים שחיו במדינה ויעצו לבני מכה לתקוף את המוסלמים במטרה לזכות בתמיכתם."}],"\xa724":[{"id":"trench","text":"המסורת אומרת כי בקרב זה נועץ מוחמד ברעהו הפרסי - סלמאן אלפראסי - שייעץ לו לחפור שוחה סביבות העיר מדינה מצפונה לו, טכניקה קרבית שלא הייתה נפוצה אצל הערבים, וכך הצליח לבלום את פלישתם של שבט קוריש לעיר."},{"id":"storm","text":"בנוסף לחפירת השוחה, סערה גדולה שפקדה את תושבי מכה גרמה להם לסגת מהעיר ולשוב למכה."}],"\xa725":[{"id":"a","term":"אלאחזאב","text":"אנשי מכה שצרו על מדינה נקראים בקוראן \\"המחנות\\" (אלאחזאב) והקוראן מתייחס אליהם ואל הסערה שפקדה אותם, בסורת המחנות (33)."}],"\xa726":[{"id":"a","text":"בהמשך לקרב זה, המסורת המוסלמית מספרת על טבח שביצעו המוסלמים בגברים של שבט בני קוריזה, אחד משלושת השבטים היהודים שחיו במדינה."},{"id":"b","text":"הגברים כאמור הוצאו להורג והנשים והילדים נמכרו לעבדים."}],"\xa727":[{"id":"a","term":"עמרה","text":"בשנת 628 חלם מוחמד בלילה כי הוא צוָּה לבצע עמרה (חג\' קטן, שלא במועד המקורי, וללא הטקסים הנוספים) סביב הכעבה בעיר מכה."},{"id":"b","text":"מוחמד ידע כי כניסתו לעיר מכה תסכן אותו שכן שבט קוריש נוטר לו טינה על הקרבות אותם ניהל נגדו במשך 6 שנים."}],"\xa728":[{"id":"a","text":"מוחמד התקרב לעיר עם פמליה מצומצמת לא חמושה, אך זה לא הספיק לבני קוריש והם עצרו אותו במקום הנקרא חודיביה."},{"id":"b","text":"מוחמד ניהל איתם משא ומתן ולבסוף חתם איתם על הסכם, שעל פניו נראה כהסכם כניעה."}],"\xa729":[{"id":"term1","text":"מוחמד לא הורשה להיכנס למכה בשנה ההיא, אלא רק בשנה שלאחריה."},{"id":"term2","text":"בנוסף, כל מי שרצה להתאסלם משבט קוריש לא חויב לעבור למדינה אלא יכל לקבל הגנה בעיר מכה."},{"id":"term3","text":"כמו כן, מוחמד נכנע גם לבני קוריש בכך שוויתר על תוארו \\"שליח אללה\\" בחתימה שלו על ההסכם, וזאת חרף דרישתו של בן דודו וחתנו, עלי בן אבי טאלב, לא לוותר על החתימה."}],"\xa730":[{"id":"a","text":"שבט קוריש טענו כי אילו היו מאמינים בהיותו שליח אללה, לא היו נדרשים כלל לחתימת ההסכם."},{"id":"b","text":"הסכם חודיביה היה לפי הדעות המקובלות באסלאם לתקופה שלא עלתה על עשר שנים."}],"\xa731":[{"id":"a","term":"הודנה","text":"הגדרת המונח \\"הודנה\\" שבאה מכוח הסכם חודיביה היא: הסכם אי לוחמה זמני של המוסלמי עם האויב (הכופר), כאשר המוסלמי נמצא בעמדת נחיתות צבאית, במטרה להתעצם ולהגיע חזק יותר לעימות הבא."}],"\xa732":[{"id":"a","text":"במשך חמישים השנים האחרונות נחתמו מספר הסכמי שלום עם מדינת ישראל ע\\"י שכנינו, שהיו לנו לאויבים עד לא מכבר."},{"id":"list","text":"למשל, מצרים (1979), ירדן (1994), הסכמי אוסלו (1993)."},{"id":"b","text":"פוסקי ההלכה (המופתים) של המדינות הנ\\"ל נדרשו לתת התייחסות האם האסלאם מאפשר לקיים הסכמי שלום עם כופרים."}],"\xa733":[{"id":"a","text":"באשר למקורות הקוראן, ישנם פסוקים שונים הקוראים למלחמה ולמולם אחרים הקוראים לשלום, ורבו הפרשנויות על אודות הפסוקים הנ\\"ל וההקשרים שלהם."}],"\xa734":[{"id":"a","term":"מצלחה","text":"באסלאם המודרני, קיים מושג אשר יסודותיו נטועים בתקופה הקלאסית אך היא מהווה מנגנון נפוץ בזרם המרכזי של האסלאם הסוני, המאפשר גמישות בפסיקת ההלכה כאשר התועלת לדת האסלאם רבה על ההפסד, והמושג נקרא \\"תועלת\\" (מצלחה בערבית)."},{"id":"b","text":"בהסכמי השלום התייחסו פוסקי ההלכה למנגנון המצלחה וגם להסכם חודיביה."}],"\xa735":[{"id":"lead","name":"ג\'ד אלחק","text":"בהקשר להסכם השלום עם מצרים, פרסם בשנת 1979 המופתי של מצרים, ג\'ד אלחק, את עיקרי הדברים הבאים:"},{"id":"points","list":["האסלאם הוא דת של ביטחון ושלום;","בשעת מלחמה חובה לקבל את ידו המושטת לשלום של האויב (מבוסס על פסוק 8:61) בקוראן;","מותר למוסלמי ליזום הסכם שלום בתנאי שתצמח לו ממנו תועלת (מצלחה) או ימנע ממנה נזק (מפסדה);","הסכם חודיביה הביא תועלת וברכה למוסלמים ואנו אופטימיים ומלאי תקווה שגם ההסכם הנוכחי יביא ניצחון שבאמצעותו נשיב את האדמה הכבושה ואת הכבוד האבוד ובמסגרתו ירושלים היקרה תשוב לחיק האסלאם תחת כנפי השלום."]}],"\xa736":[{"id":"a","text":"ג\'ד אלחק טוען כי את הסכם השלום עם ישראל נדרש לקבל מכיוון שהשליט (נשיא מצרים, סאדאת) החליט כי זו התועלת של העם המוסלמי, ולדידו של אלחק - הפעלת מנגנון ה\\"מצלחה\\" נתונה להחלטת השליט המוסלמי באשר הוא."}],"\xa737":[{"id":"lead","name":"אבן באז","text":"בהקשר להסכמי אוסלו בשנת 1993 בין מדינת ישראל לרשות הפלסטינית (אש\\"ף), כתב השיח\' אבן באז, המופתי הכללי של סעודיה את עיקרי הדברים הבאים:"},{"id":"point","text":"הודנה עם האויב בין אם מוגבלת בזמן ובין אם אינה מוגבלת מותרת אם השליט המוסלמי מצא בכך תועלת, כפי שנאמר בקוראן (8:61)."},{"id":"b","term":"צלח","text":"אבן באז הדגיש כי חרף העובדה ששבט קוריש גזל את כספי המוהג\'רון ואת בתיהם (59:8), עשה איתם הנביא הסכם (צלח) מכיוון שראה בכך תועלת לכלל המוסלמים ולמי שרוצה להתאסלם."}],"\xa738":[{"id":"lead","name":"יאסר ערפאת","text":"יצויין, כי בנאומו של יאסר ערפאת במסגד ביוהנסבורג, בשנת 1994 (הוקלט בחשאי), השווה ערפאת את הסכמי אוסלו להסכם חודיביה, וכך אמר:"},{"id":"quote","text":"ההסכם הזה אינני רואה בו יותר מההסכם אשר נחתם בין נביאנו מוחמד לקוריש. ואתם זוכרים, הח\'ליף עמר סירב להסכם הזה [...] אבל מוחמד קיבל [...]."}],"\xa739":[{"id":"a","text":"מנגד, יש מפוסקי ההלכה המוסלמים המתנגדים להסכם שלום באשר הוא עם מדינת ישראל, למשל השיח\' ד\\"ר יוסף אלקרדאוי, וטוענים כי לא ניתן להשוות את הסכם השלום עם ישראל להסכם חודיביה מטעמים שונים, ובראשם הטענה שמדינת ישראל היא תוקפנית ואינה נוטה לשלום כדברי הפסוק בקוראן 8:61"},{"id":"verse","text":"אם הם נוטים לשלום, תטה לשלום גם אתה"}],"\xa740":[{"id":"a","text":"באמנת חמאס (1988) נכתב כי פתרונות של שלום עומדים בסתירה לתפיסת העולם של תנועת ההתנגדות האסלאמית ולפיכך ויתור על חלק כלשהו מאדמת פלסטין כמוהו כזניחת חלק מן הדת."},{"id":"b","text":"בשל כך חמאס מסיקים באמנה כי הפתרון לבעיה המוסלמית הינו באמצעות ג\'האד בלבד, וכל היוזמות האחרות הינן \\"בזבוז זמן והבל.\\""}],"\xa741":[{"id":"year","text":"בשנת 246","omitted":true,"$why":"תאריך שגוי בחוברת המקור — לפי ההקשר 624. STRUCTURE.md מכריע לא להציג שנה לבני קינוקאע, כדי לא להדפיס טעות ולא לתקן את המקור. ההשמטה ממתינה לאישור המשתמשת ב-DECISIONS.md, ומודפסת בכל ריצת שער עד אז."},{"id":"qaynuqa","text":"גורשו שבט בני קינוקאע ממדינה לאזור דרום סוריה."},{"id":"nadir","text":"בשנת 625, שנה לאחר קרב בדר, גורשו שבט בני נדיר ממדינה לח\'יבר הנמצאת מצפון לה."}],"\xa742":[{"id":"a","text":"לאחר קרב השוחה בשנת 627 לא נענה מוחמד להפצרותיהם של בני קוריזה, השבט השלישי והאחרון מבין היהודים שנשאר במדינה, וחרף היותם ככל הנראה נייטרלים, האשים אותם מוחמד בקנוניה עם שבט קוריש ממכה והוציא אותם להורג."}],"\xa743":[{"id":"a","text":"לאחר הסכם חודיביה, שכלל בין היתר הפסקת הסכם הגנה בין תושבי מכה ליהודי ח\'יבר, מנהיגותו של מוחמד נסדקה במעט בשל הכניעה, לכאורה, שנאלץ להסכים לה בהסכם."},{"id":"b","text":"לאחר סכסוך על אדמות בין המוסלמים ליהודי ח\'יבר כבש מוחמד את העיר וטבח ביהודי המקום, וכך למעשה הסתיימה השפעת היהודים על אזור חצי האי ערב בתקופת מוחמד."}],"\xa744":[{"id":"a","text":"ח\'יבר הייתה בנויה ממבצרים, והקרבות התקיימו בסביבת המבצרים."},{"id":"b","text":"המסורת המוסלמית מספרת כי בקרב ההוא נתן מוחמד לעלי את נס הקרב (דגל המלחמה), לאחר שרבים מתומכיו ציפו לקבל אותו."}],"\xa745":[{"id":"a","text":"בקרב ח\'יבר השתתפו גם המהגרים הראשונים שהיגרו לחבש (אתיופיה) בראשות ג\'עפר, אחיו של עלי ובן דודו של מוחמד."},{"id":"b","text":"במסורת המוסלמית נכתב שמוחמד לקח שבוית מלחמה יהודייה בשם צפיה משבט בני נדיר, שמקורם מית\'רב."}],"\xa746":[{"id":"a","text":"האיש שהיה אחראי על טבח יהודי ח\'יבר היה עלי, בן דודו (ולימים חתנו, הח\'ליף הרביעי, והאמאם השיעי הראשון) של מוחמד."},{"id":"b","text":"לאחר כיבוש ח\'יבר נתנה לו אישה יהודייה עז צלוי במתנה, ומוחמד תלש אבר מהעז ושם אותו בפיו, אך לא בלע אותו כיוון שחש שמשהו לא כשורה."},{"id":"c","text":"בהמשך, הודתה האשה כי העז מורעל ואמרה שחשבה שמוחמד יינצל כיוון שהוא נביא. לבסוף האישה הוצאה להורג."}],"\xa747":[{"id":"a","text":"בקרב ארגוני הטרור, קרב ח\'יבר מהווה אירוע מכונן בניצחון האסלאם על היהודים."},{"id":"echo","text":"לעיתים, בתהלוכות של מחבלים באיו\\"ש וברצ\\"ע ניתן לשמוע את הסיסמא:"},{"id":"chant","text":"ח\'יבר, ח\'יבר יא יהוד; ג\'יש מוחמד ס-נעוד"},{"id":"arabic","text":"خيبر خيبر يا يهود، جيش محمد سنعود"},{"id":"meaning","text":"ח\'יבר ח\'יבר - יהודים, צבא מוחמד עוד נשוב"}],"\xa748":[{"id":"a","text":"הקוראן מתייחס להסכם חודיביה כהכרעה נחרצת (ראו סורת ההכרעה [48:1]), מהסיבה שההסכם גרם לתושבי מכה להאמין שהמוסלמים לא יפרו אותו לתקופת הזמן הקצובה."},{"id":"b","text":"האסלאם מסביר כי הראשונים להפר את ההסכם (\\"להתגרות\\" ע\\"פ קוראן 9:13) היו שבט קוריש."}],"\xa749":[{"id":"a","text":"מוחמד כבש את מכה ללא התנגדות מצד שבט קוריש בשנת 630, והקוראן מתייחס לכך שזהו ניצחון מוחלט."},{"id":"b","text":"לאחר כיבוש מכה התאסלמו רבים מתושבי העיר, ביניהם אבו סופיאן, מי שנלחם עם מוחמד בקרבות בדר ואחד, ומוחמד טיהר את הכעבה מעבודת האלילים שהייתה בו, על ידי ניתוץ הפסילים."}],"\xa750":[{"id":"a","text":"מוחמד מת בשנת 632 בגיל 63, במדינה, שם גם נקבר."},{"id":"b","text":"טרם מותו ביצע את חג\' הפרידה שם ציווה על מאמיניו לדבוק בקוראן ובסונה (המסורות הנבואיות), ולזנוח את המנהגים שהיו מקובלים בתקופת הגאהליה כמו נקמת הדם ועוד."}],"\xa751":[{"id":"a","text":"המסורת אומרת שמוחמד מת בחיקה של עאא\'שה אשתו הצעירה (בתו של אבו בכר, לימים הח\'ליף הראשון), יתכן במטרה להבליט את העובדה שמת בשיא כוחו.","omitted":true,"$omitted-note":"סבב התיקונים של המרצה (18.9.2026): „למחוק את המשפט שמוחמד מת בחיקה של עאאשה“. הקטע נשאר על הכתב, אינו מודפס."}],"\xa752":[{"id":"a","text":"בין אם מוחמד גורש ובין אם הוא זומן להיות בורר בסכסוכי השבטים, להגירה יש משמעות דתית עמוקה באסלאם. ההוכחה המרכזית לכך היא לוח השנה המוסלמי, שנקרא לוח שנה הג\'רי, שכן ספירתו מתחילה מהשנה שבה מוחמד היגר לאלמדינה. ההגירה מסמלת נטישה של סביבה עוינת על רקע דתי ומעבר לסביבה תומכת."}],"\xa753":[{"id":"a","text":"במצרים של שנות ה- 60 של המאה ה- 20, קמה קבוצת ג\'האד סלפי, מיסודו של סיד קטב (מייסד הסלפיה הג\'האדיסטית, הוצא להורג בתלייה במצרים בשנת 1966), שקראה לעצמה \\"אלתכפיר ואלהג\'רה\\" (המאשימים את האחר בכפירה באללה, והמהגרים). קבוצה זו, היגרה מהערים הגדולות במצרים לעבר כפרים שבנו לעצמם, שם התחזקו בדת האסלאם בתצורתה הג\'האדיסטית, ושבו לעשות ג\'האד במי שכונו על ידם \\"כופרים\\". לימים, סאדאת נשיא מצרים חיסל את מרבית חברי הקבוצה."}],"\xa754":[{"id":"a","text":"על גופם של מחבלי נוח\'בה שפשטו לישראל ב- 7 אוקטובר נתפסו הנחיות לשתות מדמם של היהודים, לעקור את לבם והכבד שלהם. זה עשוי להיות השראה מקרב אחד בו שתו מדמו של חמזה."}],"\xa755":[{"id":"a","text":"לאחר ה- 7 באוקטובר ניתן לשמוע גם את הסיסמה הבאה: ח\'יבר ח\'יבר יא יהוד; סאבע אוקטובר ס-יעוד (ח\'יבר ח\'יבר - יהודים; השבעה באוקטובר עוד ישוב)"}],"\xa756":[{"id":"a","text":"להרחבה על זווית הראייה של חמאס על הסכמי השלום, ראו את הניתוח המלא של ד\\"ר שגיא פולקה בקישור הבא:"}],"\xa757":[{"id":"a","text":"חשוב מאוד לציין כי ארגוני הטרור רואים בכל מה שעושים היום, חיקוי למה שמוחמד עשה בתקופת ראשית האסלאם. דת האסלאם היא \\"דת מוחמד\\" ובאה לידי ביטוי בכל תחום בחייהם. הדבר מתבטא בפסוקי קוראן המקבלים פרשנות מודרנית ובדברים נוספים שיפורטו בהמשך."}],"\xa758":[{"id":"a","text":"המסורת מספרת כי בליל צאתו ממכה התכנסו הנכבדים משבט קורייש וזממו להרוג אותו. המלאך גבריאל נגלה למוחמד וסיפר לו על זממם, ומוחמד ציווה על עלי, שהיה דומה לו, לישון במיטתו כדי להסוות את הבריחה שלו מהעיר. המסורת מספרת עוד, כי בעת בריחתו הסתתר מוחמד עם אבו בכר במערה בדרך למדינה, וכאשר רודפיו הגיעו לפתח המערה מצאו אותה חסומה עם קורי עכביש על פתחה, ולא יכלו להיכנס וכך מוחמד ניצל."},{"id":"b","text":"הקוראן מתייחס לאירוע המערה בסורה 8 פסוק 30-"}],"\xa759":[{"id":"verse","text":"הכופרים חרשו מזימה נגדך, לאוסרך או להורגך או לגרשוך [...] ואף אללה חרש מזימה, ואללה הוא הטוב שבזוממים"}],"\xa760":[{"id":"a","text":"ובסורה 9 פסוק 40 -"},{"id":"verse","text":"הנה אללה כבר עזר לו כאשר גירשוהו הכופרים [...] שניהם היו במערה והוא אמר לחברו: אל תתעצב, אללה עמנו [...] אז.. אללה... וסייע לו"}],"\xa761":[{"id":"a","text":"המשמעות היא שכאשר האויב שלנו יורה עלינו טילים, הוא סבור כי אללה הוא זה שמסייע לו בכך, שכן בראייתו זו חובה דתית להשמיד את הכופרים (מדינת ישראל)."}]}}'),x={number:d.number,title:d.title,menuTitle:d.menuTitle};function a(t){let[e,i]=t.split("."),x=(function(t){let e=d.passages[t];if(!e)throw Error(`chapter 4: unknown passage ${t}`);return e})(e).find(t=>t.id===i);if(!x)throw Error(`chapter 4: unknown fragment ${t}`);return x}function r(t){let e=a(t);if(e.page)return e.page;if(!e.text)throw Error(`chapter 4: ${t} carries no text`);return e.text}function n(t){let e=a(t);if(!e.list)throw Error(`chapter 4: ${t} carries no list`);return e.list}}}]);